from flask import Flask, request, jsonify
from hashlib import sha256
from queue import Queue
from threading import Thread

app = Flask(__name__)
storage_api_client = ...  # Implement your file storage API client here
hash_cache = {}
task_queue = Queue()

def process_file(file_url):
    with storage_api_client.open(file_url, "rb") as f:
        while True:
            block = f.read(1024 * 1024)  # Read in blocks of 1MB
            if not block:
                break
            hash_object = sha256()
            hash_object.update(block)
            final_hash = hash_object.hexdigest()

    return final_hash

def worker():
    while True:
        file_url = task_queue.get()
        hash_value = process_file(file_url)
        hash_cache[file_url] = hash_value
        task_queue.task_done()

threads = []
for _ in range(5):  # Create 5 worker threads
    worker_thread = Thread(target=worker)
    worker_thread.daemon = True
    threads.append(worker_thread)
    worker_thread.start()

@app.route("/compute_hash", methods=["POST"])
def compute_hash():
    file_url = request.json.get("file_url")
    if file_url:
        task_queue.put(file_url)
        return jsonify({"message": "Hash computation initiated."}), 202
    else:
        return jsonify({"error": "Missing 'file_url' parameter."}), 400

@app.route("/verify_hash", methods=["POST"])
def verify_hash():
    file_url = request.json.get("file_url")
    expected_hash = request.json.get("expected_hash")
    if file_url and expected_hash:
        calculated_hash = hash_cache.get(file_url)
        if calculated_hash == expected_hash:
            return jsonify({"message": "Hash verification successful."}), 200
        else:
            return jsonify({"error": "Hashes do not match."}), 409
    else:
        return jsonify({"error": "Missing 'file_url' or 'expected_hash' parameter."}), 400

if __name__ == "__main__":
    app.run(debug=True)  # Run the Flask app in debug mode```



