#include <random>
#include <mutex>
#include <atomic>

class RandomNumberService {
public:
    static RandomNumberService& createSharedInstance() {
        static std::once_flag flag;
        static RandomNumberService instance(true); // Shared instance
        std::call_once(flag, [](){ 
            // Initialize shared instance with default seed
            instance.init(); 
        });
        return instance;
    }

    static RandomNumberService* createIndependentInstance() {
        return new RandomNumberService(false); // Independent instance
    }

    int generateRandomNumber(int min, int max) const {
        // Generate random number within given range
        std::lock_guard<std::mutex> lock(mutex_);
        return generator_.operator()(min, max + 1) - min;
    }

private:
    RandomNumberService(bool shared) : isShared_(shared) {
        if (shared) {
            // Initialize with default seed
            init();
        }
    }
    ~RandomNumberService() {
        if (!isShared_) delete generator_.engine_; // Delete independent instance's engine
    }

    void init() {
        generator_.seed(std::random_device{}()); 
    }

    // Mersenne Twister-based generator (replace with desired implementation)
    std::mt19937 generator_;
    mutable std::mutex mutex_; // Protect shared state access
    bool isShared_;
};

