    public async Task<int> ExecuteParameterizedCommandAsync(List<object> values, ConnectionConfiguration config, string sqlCommand, Action<Exception>? onError = null)
    {
        try 
        {
            using (IDbConnection connection = _databaseStrategy.GetConnection(config))
            {
                // ... (Validate credentials and connection)
                if (connection == null)
                {
                    _logger.Error("Failed to establish database connection.");
                    throw new Exception("Database connection failed."); 
                }

                IDbCommand command = _databaseStrategy.CreateCommand(sqlCommand, values);
                await command.ExecuteNonQueryAsync(); 
                return await _databaseStrategy.GetAffectedRowsAsync(command);  
            }
        }
        catch (Exception ex)
        {
            _logger.Error("SQL Command execution failed.", ex);
            onError?.Invoke(ex);
            throw;
        }   
    }

