    private readonly Dictionary<string, IWeatherApi> _apis = new Dictionary<string, IWeatherApi>();
    private readonly ICache _cache;
    private readonly ILogger _logger;

    public WeatherVisualizationService(ICache cache, ILogger logger)
    {
        _cache = cache;
        _logger = logger;

        // Register weather APIs (OpenWeatherMap, AccuWeather, etc.)
        _apis.Add("openweathermap", new OpenWeatherMapApi()); 
        _apis.Add("accuweather", new AccuWeatherApi()); 
    }

    public async Task<WeatherData> GetWeatherAsync(string location, string apiName = "openweathermap")
    {
        var cachedData = _cache.GetWeatherData(location);
        if (cachedData != null)
        {
            return cachedData;
        }

        try
        {
            var api = _apis[apiName];
            var data = await api.GetWeatherAsync(location);
            _cache.SetWeatherData(location, data);
            return data;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Error fetching weather for {location} from API {apiName}");
            // Handle error gracefully (e.g., return default values or retry with another API) 
        }
    }

    // ... Other methods (e.g., GetHistoricalWeatherAsync, UpdateCachePeriodically)
