    private readonly HttpClient _httpClient;
    private readonly ILoggerFactory _loggerFactory;
    private readonly ConcurrentDictionary<string, XmlDocument> _cache = new ConcurrentDictionary<string, XmlDocument>();

    public XMLConfigurationManager(ILoggerFactory loggerFactory)
    {
        _loggerFactory = loggerFactory;
        _httpClient = new HttpClient();
    }

    public async Task<XmlDocument> GetConfigAsync(string configUri)
    {
        if (_cache.TryGetValue(configUri, out var doc))
        {
            return doc;
        }

        var content = await _httpClient.GetStringAsync(configUri);
        doc = new XmlDocument();
        doc.LoadXml(content);
        _cache.TryAdd(configUri, doc);
        return doc;
    }

    public async Task<XmlNode> QueryNodeAsync(string configUri, string xpathQuery)
    {
        var doc = await GetConfigAsync(configUri);
        return doc.SelectSingleNode(xpathQuery);
    }

    // ... Add other methods for validation, schema updates, etc. 
}


