      refreshDialogs: function(resourceId, url) {
        var deferred = $q.defer();

        const retryAttempts = 3;
        let attempt = 0;
        const backoffFactor = 2;

        function fetchData() {
          $http.get(url + resourceId)
            .then(response => {
              // Process response data for dialog fields and book names
              deferred.resolve({ books: processText(response.data), fields: updateDialogFields(response.data) });
            })
            .catch(error => {
              if (attempt < retryAttempts) {
                attempt++;
                console.error(`API request failed, retrying in ${backoffFactor ** attempt} seconds...`);
                setTimeout(fetchData, backoffFactor ** attempt * 1000); // Exponential backoff with ms delay
              } else {
                console.error('Max retries exceeded:', error);
                deferred.reject(error);
              }
            });
        }

        fetchData();

        return deferred.promise;
      }
    };
  });
})();



