import json
import asyncio
import aiohttp

class JSONFactory:
    registry = {}

    def register(self, id, factory):
        self.registry[id] = factory

    async def create(self, id):
        factory = self.registry.get(id)
        if factory:
            return await factory()
        else:
            raise ValueError(f"Factory for ID '{id}' not found.")

class JSONParser:
    def __init__(self, schema_url=None):
        self.schema_url = schema_url

    async def load_json(self, file_path):
        try:
            with open(file_path, 'r') as f:
                return json.load(f)
        except FileNotFoundError:
            raise ValueError(f"File '{file_path}' not found.")

    async def extract_sequence_number(self, file_path, field_name):
        data = await self.load_json(file_path)
        array = data.get(field_name)
        if array:
            array.sort()
            last_element = array[-1]
            try:
                sequence_number = int(last_element['sequence'])
                return sequence_number
            except (KeyError, TypeError):
                raise ValueError(f"Invalid sequence number format in '{field_name}' field.")
        else:
            raise ValueError(f"Field '{field_name}' not found in JSON data.")

# Example usage:
async def main():
    json_parser = JSONParser() 

    sequence_number = await json_parser.extract_sequence_number("data.json", "array_field")
    print(f"Sequence Number: {sequence_number}")

if __name__ == "__main__":
    asyncio.run(main())  
```



