#include <iostream>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <thread>
#include <map>

// ... (Implementation of logging services: cloudAPI, diskStorage, database) ...

class Logger {
public:
    enum LogLevel { DEBUG, INFO, WARNING, ERROR, CRITICAL };

    Logger() : logLevel(INFO) {}

    void setLogLevel(LogLevel level) { 
        std::lock_guard<std::mutex> lock(logLevelMutex);
        logLevel = level;
    }

    void log(LogLevel level, const std::string& message) {
        if (level >= logLevel) {
            // Acquire lock for thread safety in logging queue
            std::lock_guard<std::mutex> lock(logQueueMutex);
            logQueue.push({level, message}); 
            cv.notify_one(); // Notify processing threads
        }
    }

    void start() {
        // Start background threads for each logging service
        for (auto& service : services) {
            serviceThread = std::thread([&service]() { 
                while (true) {
                    std::unique_lock<std::mutex> lock(logQueueMutex);
                    cv.wait(lock, [this] { return !logQueue.empty(); }); 

                    auto logEntry = logQueue.front();
                    logQueue.pop();
                    lock.unlock();

                    // Route and process log entry based on service type
                    service->processLog(logEntry); 
                }
            });
        }
    }

    void stop() {
        // Signal threads to stop gracefully (e.g., using a flag)
    }

private:
    LogLevel logLevel;
    std::mutex logLevelMutex;
    std::queue<std::pair<LogLevel, std::string>> logQueue;
    std::condition_variable cv; 
    std::mutex logQueueMutex; 

    // ... (Service integration and routing logic) ...  
};



int main() {
    Logger logger;
    logger.start(); // Start logging threads

    // ... (Application code that uses the Logger) ...

    logger.stop(); // Graceful shutdown of logging threads

    return 0; 
}
``` 


**Key Concepts:**

* **Concurrency:**  Multiple threads are used to handle different logging services concurrently, preventing bottlenecks.
* **Configuration:**  `logLevel` can be dynamically adjusted without restarting the application.
* **Routing:** Log messages are routed to appropriate services based on their type and priority.
* **Error Handling:** The framework should gracefully degrade if external logging services are unavailable (e.g., retrying, using a fallback service).
* **Extensibility:** The architecture allows for easy integration of new logging services in the future.



**Remember:**

This is a simplified example. A production-ready system would require much more detailed implementation, error handling, performance tuning, and testing.  


