public class FileLoader implements Runnable {

    private final String filePath;
    private final ConcurrentHashMap<String, MoSTState> cache = new ConcurrentHashMap<>();

    public FileLoader(String filePath) {
        this.filePath = filePath;
    }

    @Override
    public void run() {
        try (FileInputStream fis = new FileInputStream(filePath)) {
            Yaml yaml = new Yaml();
            MoSTState state = yaml.loadAs(fis, MoSTState.class); // Deserialize object

            // Validate file format, version control, etc.

            cache.put(state.getId(), state); // Store in cache for concurrent access
        } catch (IOException e) {
            // Handle errors gracefully, log exceptions, retry if applicable
        }
    }

    public MoSTState loadState(String id) {
        return cache.get(id);
    }
}



