class TransactionProcessor {

 public: 
    TransactionProcessor(int numThreads, int batchSize) : 
        numThreads_(numThreads), 
        batchSize_(batchSize) {}

    void start() {
      for (int i = 0; i < numThreads_; ++i) {
          threads_.emplace_back([this] { processTransactions(); });
      }
    }

    void stop() {
      // Implement graceful shutdown logic here
      stopSignal_ = true;
      cv_.notify_all(); 

      for (auto& thread : threads_) {
          thread.join();
      }
    }

    void addTransaction(const TransactionData& transaction) {
      std::unique_lock<std::mutex> lock(transactionQueueMutex_);
      transactionQueue_.push(transaction);
      cv_.notify_one(); 
    }


 private:

    void processTransactions() {
      while (!stopSignal_) { 
          TransactionData transaction;

          // Acquire lock to access the queue
          std::unique_lock<std::mutex> lock(transactionQueueMutex_);
          cv_.wait(lock, [this] { return !transactionQueue_.empty() || stopSignal_; });

          if (!stopSignal_) {
              transaction = transactionQueue_.front(); 
              transactionQueue_.pop();
          }
          // Process the transaction here
          if (!processTransaction(transaction)) {
            // Handle error and potentially retry or move to a different queue for retries
          } 
      }  
    }


    bool processTransaction(const TransactionData& transaction) {
        // Implement your payment gateway API interaction logic here 

        // ... (API call, validation, logging, etc.) ...

        return true; // Indicate success or failure
    }


    int numThreads_;
    int batchSize_;

    std::vector<std::thread> threads_;
    std::queue<TransactionData> transactionQueue_;
    std::mutex transactionQueueMutex_;
    std::condition_variable cv_;
    bool stopSignal_ = false; 
};



