public class HttpUpdateService 
{
    private readonly IValidator<ElementSchema> _validator;
    private readonly IDistributedLockProvider _lockProvider;
    private readonly IServiceBus _serviceBus;
    private readonly ILogger<HttpUpdateService> _logger;

    public HttpUpdateService(IValidator<ElementSchema> validator, 
                            IDistributedLockProvider lockProvider, 
                            IServiceBus serviceBus, 
                            ILogger<HttpUpdateService> logger)
    {
        _validator = validator;
        _lockProvider = lockProvider;
        _serviceBus = serviceBus;
        _logger = logger;
    }

    public async Task<HttpResponseMessage> UpdateElementAsync(string pageSectionId, string elementId, string htmlContent)
    {
        var schema = new ElementSchema { PageSectionId = pageSectionId, ElementId = elementId, HtmlContent = htmlContent };

        if (!_validator.Validate(schema))
        {
            _logger.LogError("Validation failed: {Schema}", schema);
            return new HttpResponseMessage(HttpStatusCode.BadRequest);
        }

        using (var lock = await _lockProvider.AcquireLockAsync($"element-{pageSectionId}-{elementId}"))
        {
            try
            {
                await _serviceBus.PublishUpdateElementCommand(schema);
                return new HttpResponseMessage(HttpStatusCode.OK);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error updating element: {Schema}", schema);
                return new HttpResponseMessage(HttpStatusCode.InternalServerError);
            }
        } 
    }
}

