struct LogEntry {
    int userId;
    std::chrono::system_clock::time_point timestamp;
    std::string eventType;
    int duration;
    std::string location;
};

class UserDurationTracker {
private:
    std::mutex mutex_;
    std::queue<LogEntry> recentLogs_[100]; // Limit recent logs for each user
    std::unordered_map<int, double> avgDurations_;

public:
    void processLogEntry(const LogEntry& logEntry) {
        std::lock_guard<std::mutex> lock(mutex_);
        recentLogs_[logEntry.userId].push(logEntry);
        if (recentLogs_[logEntry.userId].size() > 3) {
            recentLogs_[logEntry.userId].pop(); // Keep only the last three logs
        }
        calculateAverageDuration(logEntry.userId);
    }

    void calculateAverageDuration(int userId) {
        std::lock_guard<std::mutex> lock(mutex_);
        double sum = 0;
        for (const auto& log : recentLogs_[userId]) {
            sum += log.duration;
        }
        avgDurations_[userId] = sum / recentLogs_[userId].size();
    }

    double getAvgDuration(int userId) {
        std::lock_guard<std::mutex> lock(mutex_);
        return avgDurations_.at(userId);
    }
};


// Implement the main processing logic 
int main() {
    Logger logger;
    TimeSeriesDatabase db;
    UserDurationTracker tracker;

    // ... (Implementation for reading log files, handling concurrency, backpressure, etc.)

    return 0;
}

```



