#include <iostream>
#include <mutex>
#include <thread>
#include <queue>
#include <condition_variable>

class Logger {
 public:
  enum LogLevel { DEBUG, INFO, WARNING, ERROR };
  Logger(LogLevel defaultLevel) : level_(defaultLevel) {}

  void log(LogLevel level, const std::string& message) {
    std::unique_lock<std::mutex> lock(mutex_);
    if (level >= level_) {
      // Timestamping and formatting logic here
      log_queue_.push(message);
      cv_.notify_one();
    }
  }

 private:
  LogLevel level_;
  std::mutex mutex_;
  std::condition_variable cv_;
  std::queue<std::string> log_queue_;

  void processLogs() {
    while (true) {
      std::unique_lock<std::mutex> lock(mutex_);
      cv_.wait(lock, [this] { return !log_queue_.empty() || shutdown_; });
      if (shutdown_) break;

      // Log message from queue to various backends here
    }
  }

  bool shutdown_ = false;
};


int main() {
  Logger logger(Logger::INFO); 
  std::thread logProcessor([&logger](){ logger.processLogs(); });

  // Logging from different threads and instances
  logger.log(Logger::DEBUG, "This is a debug message");
  logger.log(Logger::INFO, "This is an info message");
  // ...

  // Shutdown logging system gracefully
  logger.shutdown_ = true;
  cv_.notify_all();
  logProcessor.join();

  return 0;
}
```



