        [HttpPost]
        public async Task<IActionResult> UpdateContent([FromBody] UpdateRequest request)
        {
            if (!ModelState.IsValid) 
            {
                return BadRequest(ModelState);
            }

            var result = await HandleUpdateAsync(request);
            return Ok(result);
        }

        private async Task<UpdateResponse> HandleUpdateAsync(UpdateRequest request)
        {
            try
            {
                // Fetch and validate metadata from CMS
                var metadata = await _cms.GetMetadataAsync(request.PageId, request.ElementId); 

                if (metadata == null)
                {
                    _logger.LogError("Failed to retrieve metadata for page {pageId}, element {elementId}", request.PageId, request.ElementId);
                    return new UpdateResponse { ErrorMessage = "Metadata retrieval failed" };
                }

                // Construct updated HTML content 
                var updatedHtml = ...; 

                // Compute MD5 hash of the updated content
                var md5Hash = System.Security.Cryptography.MD5.ComputeHash(System.Text.Encoding.UTF8.GetBytes(updatedHtml));
                return new UpdateResponse { Md5Hash = Convert.ToBase64String(md5Hash) };

            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error updating content for page {pageId}, element {elementId}", request.PageId, request.ElementId);
                return new UpdateResponse { ErrorMessage = "An error occurred during update" }; 
            }
        }
