void* fetchResourceChunk(void* args) {
  struct FetchArgs* params = (FetchArgs*)args;

  if (authenticate_resource(params->path, params->token) != 0) {
    // Handle authentication error
    fprintf(stderr, "Authentication failed for %s\n", params->path);
    return NULL;
  }

  // Open resource file
  FILE* fp = fopen(params->path, "rb");
  if (fp == NULL) {
    // Handle I/O error
    fprintf(stderr, "Failed to open %s\n", params->path);
    return NULL;
  }

  fseek(fp, params->start_byte, SEEK_SET); 
  size_t bytes_read = fread(params->buffer, 1, params->chunk_size, fp);
  fclose(fp);

  // Handle potential read errors
  if (bytes_read != params->chunk_size) {
    // Error handling for incomplete read
  }

  pthread_exit(NULL);
}

struct FetchArgs {
  const char* path; 
  const char* token; 
  char* buffer;
  size_t chunk_size;
  size_t start_byte;
};


int main() {
  // Example usage:
  struct FetchArgs args = {
    .path = "file.txt",
    .token = "your_oauth2_token",
    .buffer = malloc(1024), 
    .chunk_size = 1024,
    .start_byte = 512, 
  };

  pthread_t thread;
  pthread_create(&thread, NULL, fetchResourceChunk, &args);
  pthread_join(thread, NULL);

  // Use the fetched data (args.buffer)
  free(args.buffer);

  return 0;
}
