// C Function
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
  char** items;
  size_t size;
} resource_bundle_t;

int load_resource_bundle(const char *path, struct resource_bundle **bundle) {
  FILE *fp = fopen(path, "r");
  if (fp == NULL) {
    return 1; // Error opening file
  }

  fseek(fp, 0, SEEK_END);
  long size = ftell(fp);
  rewind(fp);

  char *buffer = malloc(size + 1);
  if (buffer == NULL) {
    fclose(fp);
    return 2; // Error allocating memory
  }

  fread(buffer, 1, size, fp);
  buffer[size] = '\0';
  fclose(fp);

  char *item = strtok(buffer, "\n");
  size_t count = 0;
  while (item != NULL) {
    count++;
    item = strtok(NULL, "\n");
  }

  *bundle = malloc(sizeof(resource_bundle_t));
  if (*bundle == NULL) {
    free(buffer);
    return 3; // Error allocating memory
  }

  (*bundle)->items = malloc(count * sizeof(char *));
  if ((*bundle)->items == NULL) {
    free(*bundle);
    free(buffer);
    return 4; // Error allocating memory
  }

  item = strtok(buffer, "\n");
  for (size_t i = 0; i < count; i++) {
    (*bundle)->items[i] = strdup(item);
    if ((*bundle)->items[i] == NULL) {
      free((*bundle)->items);
      free(*bundle);
      free(buffer);
      return 5; // Error allocating memory
    }
    item = strtok(NULL, "\n");
  }

  (*bundle)->size = count;
  free(buffer);

  return 0; // Success
}



```']

