typedef struct {
    NFAPI_CRC_INDICATION_PDU_T **array; 
    size_t size;
    size_t capacity;
} CRCArrayManager;

pthread_mutex_t lock; 
static CRCArrayManager *manager = NULL;

// Function to initialize the array manager
int init_crc_array_manager(size_t initial_capacity) {
    manager = (CRCArrayManager *)malloc(sizeof(CRCArrayManager));
    if (!manager) {
        fprintf(stderr, "Memory allocation failed!\n");
        return -1;
    }

    manager->array = (NFAPI_CRC_INDICATION_PDU_T **)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!manager->array) {
        fprintf(stderr, "Memory allocation failed!\n");
        free(manager);
        return -1;
    }

    manager->size = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&lock, NULL); // Initialize mutex for thread safety
    return 0;
}


// Function to add a CRC indication PDU to the array
int add_crc_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&lock); // Acquire lock for thread safety

    if (manager->size >= manager->capacity) { 
        // Resize the array if capacity is full
        manager->capacity *= 2;  // Double the capacity
        manager->array = (NFAPI_CRC_INDICATION_PDU_T **)realloc(manager->array, manager->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
        if (!manager->array) {
            pthread_mutex_unlock(&lock);
            fprintf(stderr, "Memory allocation failed!\n");
            return -1; // Handle memory allocation error
        }
    }

    manager->array[manager->size] = pdu; 
    manager->size++;

    pthread_mutex_unlock(&lock); // Release the lock

    // Optional: Log the addition of the PDU or store it in the distributed data store here
    return 0;
}


// ... (Add other functions like retrieve_crc_pdu, remove_crc_pdu, etc. with similar thread-safe implementations)



