#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>

int run_command(const char *cmd) {
    pid_t pid = fork();
    if (pid == 0) {
        // Child process executes the command
        char* args[] = { const_cast<char*>(cmd), NULL };
        execvp(args[0], args);
        perror("execvp");
        exit(1);
    } else if (pid > 0) {
        // Parent process waits for the child to finish
        wait(NULL);
        return 1;
    } else {
        perror("fork");
        return 0;
    }
}
