            continue;
        }
        functions[i].function = dlsym(functions[i].handle, FUNCTION_NAME_TEMPLATE);
        if (!functions[i].function) {
            fprintf(stderr, "Failed to find symbol: %s\n", FUNCTION_NAME_TEMPLATE);
