    json_error_t error;
    json_object *root = json_load_string(token_response, &error);
    if (error.type != JSON_ERROR_NONE) {
        // Log parsing error 
        return 0; // Invalid Token - Parse Error
    }

    json_object *access_token = json_object_get(root, "access_token");
    if (json_object_is_null(access_token)) {
        // Log missing access token error
        json_decref(root);
        return 0; // Invalid Token - Missing Access Token
    }

    json_object *expires_in = json_object_get(root, "expires_in");
    if (json_object_is_null(expires_in) || !json_object_is_number(expires_in)) {
        // Log expires_in error
        json_decref(root);
        return 0; // Invalid Token - Missing or Invalid Expires In
    }

    // ... (Validate other fields like token_type, refresh_token)

