void insertAfterOrAppend(std::forward_list<std::string>& feed, const std::string& firstString, const std::string& secondString) {
  Metadata metadata;

  {
    std::unique_lock<std::mutex> lock(apiMutex);
    // Retry logic with exponential backoff
    int retries = 0;
    while (retries < 3 && !fetchMetadata(firstString, metadata)) {
      retries++;
      std::this_thread::sleep_for(std::chrono::milliseconds(1 << retries)); // Exponential backoff
    }

    if (retries >= 3) {
      // Log failure to handle API errors appropriately
      return;
    }
  }

  auto it = feed.before_begin();
  for (; it != feed.end(); ++it) {
    if (*it == firstString) {
      break;
    }
  }
  if (it != feed.end()) {
    feed.insert_after(it, secondString); 
  } else {
    feed.push_back(secondString);
  }

}


