function generateFooterScripts() {
  const scriptDefinitions = readScriptDefinitions('./scripts/'); 

  const essentialScripts = scriptDefinitions.filter(script => script.type === 'essential');
  const optionalScripts = scriptDefinitions.filter(script => script.type === 'optional');
  const deferredScripts = scriptDefinitions.filter(script => script.type === 'deferred');

  return `
    <footer>
      ${generateScriptTags(essentialScripts)}
      ${generateScriptTags(optionalScripts)}
      ${generateScriptTags(deferredScripts)}
    </footer>
  `;
}

function generateScriptTags(scripts) {
  return scripts.map(script => {
    return `
      <script 
        src="${script.source}" 
        type="${script.type}" 
        name="${script.name}" 
