public async Task<bool> ValidateOAuth2TokenAsync(string tokenResponse)
{
    try
    {
        var tokenData = JsonSerializer.Deserialize<dynamic>(tokenResponse);

        if (tokenData == null ||
            !tokenData.ContainsKey("access_token") ||
            !tokenData.ContainsKey("expires_in") ||
            !tokenData.ContainsKey("token_type"))
        {
            return false;
        }

        if (tokenData["token_type"].ToString() != "Bearer" ||
            !int.TryParse(tokenData["expires_in"].ToString(), out var expiresIn) || 
            expiresIn <= 0)
        {
            return false;
        }

        // ... Additional validation logic, e.g., refresh_token check

        return true; 
    }
    catch (Exception ex)
    {
        // Log the exception and handle gracefully
        Console.WriteLine($"Error validating OAuth2 token: {ex.Message}");
        return false;
    }
}

```

