#include <mutex>
#include <condition_variable>
#include <queue>
#include <thread>

class LogEntry {
public:
    LogEntry(const std::string& message, const std::string& source) : message(message), source(source) {}
    std::string message;
    std::string source;
};

class DistributedLogger {
private:
    std::mutex mutex_;
    std::condition_variable cv_;
    std::queue<LogEntry> logBuffer_;
    int bufferSize_;

public:
    DistributedLogger(int bufferSize) : bufferSize_(bufferSize) {}

    void insertLogEntry(const std::string& message, const std::string& source) {
        { 
            std::lock_guard<std::mutex> lock(mutex_);
            logBuffer_.push(LogEntry(message, source)); 
        }
        cv_.notify_one(); 
    }

    void processLogEntries() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this] { return !logBuffer_.empty() || stopping_; });

            if (stopping_) break; 

            // Process log entries from the buffer
            LogEntry entry = logBuffer_.front();
            logBuffer_.pop();
            lock.unlock();

            // Send log entry to cloud service API asynchronously
            // ... handle errors and retries here ...
        }
    }

    void stop() {
        { 
            std::lock_guard<std::mutex> lock(mutex_);
            stopping_ = true;
        }
        cv_.notify_all(); 
    }

private:
    bool stopping_ = false;
};


```



