async function loadAndExecuteScript(scriptUrl) {
  try {
    const response = await fetch(scriptUrl);
    if (!response.ok) {
      throw new Error(`Failed to load script: ${scriptUrl} (${response.status})`);
    }

    const script = await response.text();
    const scriptElement = document.createElement('script');
    scriptElement.textContent = script;
    document.head.appendChild(scriptElement);
  } catch (error) {
    console.error(`Error loading or executing script: ${scriptUrl}`, error);

    // Implement fallback mechanisms, retry logic, and/or alternative scripts here
  }
}

// Example usage with dependency management
