// Structure to represent a semaphore pool entry
typedef struct {
    sem_t *semaphore;
    int initial_value;
} SemaphoreEntry;

// Global semaphore pool
SemaphoreEntry *pool = NULL;
int pool_size = 0;

// Function prototypes
void *init_semaphores(void *arg);
void release_semaphores();
sem_t *get_semaphore(int index);

int main() {
    pthread_t thread;
    // Initialize semaphore pool based on configuration (e.g., from a config file)
    pool_size = 10; // Example size
    pool = malloc(sizeof(SemaphoreEntry) * pool_size);
    if (pool == NULL) {
        perror("Memory allocation failed");
        exit(1);
    }

    // Initialize semaphores in a separate thread to avoid blocking the main thread
    pthread_create(&thread, NULL, init_semaphores, NULL);
    pthread_join(thread, NULL);

    // ... rest of your web server logic using the semaphore pool

    release_semaphores(); // Release resources when done
    return 0;
}

void *init_semaphores(void *arg) {
    for (int i = 0; i < pool_size; i++) {
        pool[i].initial_value = 5; // Example initial value
        pool[i].semaphore = sem_open("sem_" + i, O_CREAT | O_EXCL, 0644, pool[i].initial_value);
        if (pool[i].semaphore == SEM_FAILED) {
            perror("Semaphore creation failed");
            // Handle error appropriately: retry, fallback, logging etc.
        }
    }
    return NULL;
}

void release_semaphores() {
    for (int i = 0; i < pool_size; i++) {
        sem_close(pool[i].semaphore);
        sem_unlink("sem_" + i);
    }
    free(pool);
}

sem_t *get_semaphore(int index) {
    // Implement logic to retrieve a semaphore from the pool based on index
    return NULL; 
}



