        "EDE" => des::ede_encrypt(plaintext, key),
        "EDE3" => des::ede3_encrypt(plaintext, key),
        "CFB" => des::cfb_encrypt(plaintext, key),
        _ => Err("Invalid cipher mode".to_string()),
    }
}

pub fn decrypt(ciphertext: &[u8], mode: &str, key: &[u8]) -> Result<Vec<u8>, String> {
