        "ECB" => des::ecb_decrypt(ciphertext, key),
        "EDE" => des::ede_decrypt(ciphertext, key),
        "EDE3" => des::ede3_decrypt(ciphertext, key),
        "CFB" => des::cfb_decrypt(ciphertext, key),
        _ => Err("Invalid cipher mode".to_string()),
