    const char* what() const noexcept override { return message_.c_str(); }

private:
    std::string message_;
};

template <typename T>
class DeserializableObject {
public:
    DeserializableObject(const std::string& id) : id_(id) {}

    virtual ~DeserializableObject() = default;

    virtual T* deserialize(const std::vector<unsigned char>& data) = 0;

protected:
    std::string id_;
};

class Deserializer {
public:
    static std::map<std::string, std::function<std::shared_ptr<DeserializableObject>()(const std::vector<unsigned char>&)>> getDeserializersMap() {
        // Initialize deserializer map here. 
        return {};
    }

private:
    // ... (Private methods for handling serialization errors, retry logic, etc.)
};

std::shared_ptr<DeserializableObject> deserialize(const std::string& className, const std::vector<unsigned char>& data) {
    auto deserializerMap = Deserializer::getDeserializersMap();
    auto it = deserializerMap.find(className);
    if (it == deserializerMap.end()) {
        throw DeserializationError("Unknown class name: " + className);
    }
    try {
        return it->second(data); 
    } catch (const std::exception& e) {
        // Handle deserialization errors, logging, retries, etc.
        throw;
    }
}

}  // namespace DataDeserializer



