async function generateAndInsertComponents(sectionId, componentTypes) {
  const response = await fetch('https://api.example.com/components', {
    headers: {
      'Authorization': 'Bearer YOUR_API_TOKEN' 
    }
  });

  if (!response.ok) {
    throw new Error('Network response was not ok');
  }

  const data = await response.json();

  let html = '';

  for (const type of componentTypes) {
    const matchingComponents = data.filter(component => component.type === type);
    if (matchingComponents.length > 0) {
      html += matchingComponents.map(component => {
        // Render individual component using framework's methods
        return  `<div class="component-${component.type}">${renderComponent(component)}</div>`; 
      }).join('');
    } else {
      html += `<p>No components found of type ${type}</p>`;
    }
  }

  document.getElementById(sectionId).innerHTML = html;
  return html; 
}
``` 



