// ... (OAuth2 Token Validation Component Implementation)

public async Task<bool> ValidateToken(string tokenResponse)
{
    // Deserialize JSON response
    // ... 

    // Validate required fields: access_token, expires_in, token_type
    if (string.IsNullOrEmpty(tokenResponse["access_token"]) ||
        !int.TryParse(tokenResponse["expires_in"], out int expiresIn) ||
        expiresIn <= 0 ||
        tokenResponse["token_type"] != "Bearer")
    {
        return false;
    }

    // Optional: Validate refresh_token

    return true; 
}

public class TokenHandler : IHttpHandler
{
    private readonly ITokenValidator _validator;
    private readonly ICacheService _cache;

    // ... (Constructor and other methods)

    public async Task<HttpResponseMessage> Post(HttpRequestMessage request)
    {
        // Read token response from request body
        string tokenResponse = await request.Content.ReadAsStringAsync();

        // Cache validated tokens 
        var cachedResult = _cache.Get(tokenResponse);
        if (cachedResult != null)
        {
            return Request.CreateResponse(HttpStatusCode.OK, cachedResult);
        }

        bool isValid = await _validator.ValidateToken(tokenResponse);

        // Store validated result in cache
        _cache.Set(tokenResponse, isValid);

        return Request.CreateResponse(isValid ? HttpStatusCode.OK : HttpStatusCode.BadRequest);
    }
} 


```



