#include <mutex>
#include <condition_variable>

class LogEntry {
public:
  LogEntry(const std::string& message, const std::string& source) : 
    message(message), source(source) {}

  std::string message;
  std::string source;
};

class LogBuffer {
private:
  std::vector<LogEntry> entries;
  int capacity;
  std::mutex mutex;
  std::condition_variable cv;

public:
  LogBuffer(int size) : capacity(size) {}

  void insert(const LogEntry& entry) {
    std::unique_lock<std::mutex> lock(mutex);
    while (entries.size() >= capacity) {
      cv.wait(lock); 
    }
    entries.push_back(entry);
    cv.notify_one(); // Notify waiting thread
  }

  // ... other methods for retrieving log entries, truncation, etc. ...
};

void insertLogEntry(const LogEntry& entry) {
  static LogBuffer buffer(1024); // Replace with appropriate buffer size
  buffer.insert(entry);
}
