// AesGcmDecryptor.cs
using System;
using System.Security.Cryptography;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;

public class AesGcmDecryptor
{
    private readonly string _key;
    private readonly string _iv;
    private readonly ILogger<AesGcmDecryptor> _logger;
    private readonly IDataStorage _dataStorage; 

    public AesGcmDecryptor(IConfiguration configuration, ILogger<AesGcmDecryptor> logger, IDataStorage dataStorage)
    {
        _key = configuration["DecryptionKey"];
        _iv = configuration["InitializationVector"];
        _logger = logger;
        _dataStorage = dataStorage;
    }

    public async Task<string> DecryptAsync(byte[] encryptedData)
    {
        try
        {
            using (var aes = Aes.Create())
            {
                aes.Key = Convert.FromBase64String(_key);
                aes.IV = Convert.FromBase64String(_iv);
                aes.Mode = CipherMode.GCM;

                using (var decryptor = aes.CreateDecryptor())
                {
                    using (var memoryStream = new MemoryStream(encryptedData))
                    {
                        byte[] decryptedBytes = decryptor.TransformFinalBlock(memoryStream.ToArray(), 0, memoryStream.Length);
                        return System.Text.Encoding.UTF8.GetString(decryptedBytes);
                    }
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error decrypting data.");
            throw; // Re-throw for application-level handling
        }
    }
}
