void insertAfterFirstOccurrence(std::forward_list<std::string>& lst, const std::string& searchStr, const std::string& insertStr) {
    auto before = lst.before_begin();
    for (auto it = lst.begin(); it != lst.end(); ++it) {
        if (*it == searchStr) {
            lst.insert_after(before, insertStr);
            return;
        }
        before = it;
    }
}
