class DynamicCacheManager:
    def __init__(self, backends):
        self.backends = backends  # Collection of configured backend instances
        self.selection_policy = BackendSelectionPolicy() # Policy for choosing the best backend

    def get(self, key):
        backend = self.selection_policy.select_backend()
        try:
            return backend.get(key)
        except Exception as e:
            # Handle errors, retry or fallback to a different backend
            print(f"Error retrieving from {backend}: {e}")
            return self.get(key)  # Retry with a different backend

    def set(self, key, value, expiration=None):
        backend = self.selection_policy.select_backend()
        try:
            backend.set(key, value, expiration)
        except Exception as e:
            print(f"Error setting to {backend}: {e}")

    def delete(self, key):
        backend = self.selection_policy.select_backend()
        try:
            backend.delete(key)
        except Exception as e:
            print(f"Error deleting from {backend}: {e}")


