typedef struct {
    pthread_mutex_t lock;  
    int num_semaphores;
    sem_t **semaphore_pool;
} SemaphorePool;

SemaphorePool *create_semaphore_pool(int initial_size) {
    SemaphorePool *pool = malloc(sizeof(SemaphorePool));
    pthread_mutex_init(&pool->lock, NULL);
    pool->num_semaphores = initial_size;
    pool->semaphore_pool = calloc(initial_size, sizeof(sem_t*)); 
    // ... initialize semaphores in the pool ...
    return pool;
}

void destroy_semaphore_pool(SemaphorePool *pool) {
    for (int i = 0; i < pool->num_semaphores; i++) {
        sem_destroy(pool->semaphore_pool[i]);  
    }
    free(pool->semaphore_pool);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

// ... Functions for acquiring and releasing semaphores, dynamically resizing the pool ... 

// ... Logging functions for semaphore operations ...



