// DynamicRandomValueGenerator Library (Simplified Example)

public class RandomValueContext
{
    private readonly Random _random;
    private readonly int _min;
    private readonly int _max;

    public RandomValueContext(int min, int max)
    {
        _min = min;
        _max = max;
        _random = new Random(); 
    }

    public int GenerateInteger() => _random.Next(_min, _max + 1);
    public double GenerateFloat() => _random.NextDouble() * (_max - _min + 1) + _min;
}

public class DynamicRandomValueGenerator
{
    private readonly Dictionary<string, RandomValueContext> _contexts = new();

    public void AddContext(string name, int min, int max)
    {
        _contexts.Add(name, new RandomValueContext(min, max)); 
    }

    public int GenerateInteger(string contextName) => _contexts[contextName].GenerateInteger();
    public double GenerateFloat(string contextName) => _contexts[contextName].GenerateFloat();
}

