  std::string timestamp;
  std::string level;
  std::string message;
};

class LogBuffer {
 public:
  void enqueue(LogEntry entry) {
    std::unique_lock<std::mutex> lock(mutex_);
    buffer_.push(entry);
    cv_.notify_one(); 
  }

  LogEntry dequeue() {
    std::unique_lock<std::mutex> lock(mutex_);
    cv_.wait(lock, [this]{return !buffer_.empty();});
    LogEntry entry = buffer_.front();
    buffer_.pop();
    return entry;
