public:
    LogManager(int maxEvents) : eventsQueue(maxEvents) {}

    void addEvent(const LOG_EVENT_RECORD& event) {
        std::unique_lock<std::mutex> lock(eventsMutex);
        eventsQueue.push(event);
        conditionVariable.notify_one();
    }

    void processEvents() {
        while (true) {
            std::unique_lock<std::mutex> lock(eventsMutex);
            conditionVariable.wait(lock, [this] { return !eventsQueue.empty(); });

            LOG_EVENT_RECORD event = eventsQueue.front();
            eventsQueue.pop();
            lock.unlock();

            // Process the event (e.g., send to Kinesis)
        }
    }

private:
