    public VideoStreamingAnalyticsService(int port) {
        this.port = port;
        // Define gRPC service implementation 
        VideoAnalyticsServiceImpl serviceImpl = new VideoAnalyticsServiceImpl();
        // Create server and register the service
        server = ServerBuilder.forPort(port)
                .addService(serviceImpl)
                .build();
    }

    public void start() {
        listenFuture = server.startAsync();
        Futures.addCallback(listenFuture, new FutureCallback<>() {
            @Override
            public void onSuccess(Server server) {
                System.out.println("Server started on port " + port);
            }

            @Override
            public void onFailure(Throwable t) {
                System.err.println("Failed to start server: " + t.getMessage());
            }
        }, MoreExecutors.sameThreadExecutor()); 
    }


    // ... (Additional methods for handling shutdown, configuration, etc.)

    public static void main(String[] args) {
        int port = 50051; // Example port
        VideoStreamingAnalyticsService service = new VideoStreamingAnalyticsService(port);
        service.start();
    }

}


