using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

public class RealTimeDataProcessorService
{
    private readonly IMessageQueue _messageQueue;
    private readonly IJsonDeserializer _jsonDeserializer;
    private readonly IAggregator _aggregator;
    private readonly IDataWriter _dataWriter;
    private readonly IDistributedLockManager _lockManager;

    public RealTimeDataProcessorService(IMessageQueue messageQueue, 
                                      IJsonDeserializer jsonDeserializer,
                                      IAggregator aggregator,
                                      IDataWriter dataWriter,
                                      IDistributedLockManager lockManager)
    {
        _messageQueue = messageQueue;
        _jsonDeserializer = jsonDeserializer;
        _aggregator = aggregator;
        _dataWriter = dataWriter;
        _lockManager = lockManager;
    }

    public async Task ProcessDataAsync()
    {
        while (true)
        {
            var messageBatch = await _messageQueue.ReceiveBatchAsync();

            if (messageBatch != null)
            {
                await ProcessBatchAsync(messageBatch);
            }
        }
    }

    private async Task ProcessBatchAsync(List<string> jsonPayloads)
    {
        // 1. Deserialize JSON payloads
        var data = jsonPayloads.Select(_jsonDeserializer.Deserialize).ToList();

        // 2. Acquire distributed lock for batch processing
        if (_lockManager.AcquireLock("batch-processing"))
        {
            try
            {
                // 3. Aggregate and transform data
                var aggregatedResults = _aggregator.Aggregate(data);

                // 4. Write results to output
                _dataWriter.WriteData(aggregatedResults);
            }
            finally
            {
                _lockManager.ReleaseLock("batch-processing");
            }
        }
        else
        {
            // Handle lock contention - retry or queue for later processing
            Console.WriteLine("Lock contention detected. Retrying...");
        }
    }
}

