struct DomainCacheEntry {
    ttl: Duration,
    status: String, // e.g., "available", "unavailable"
}

struct DNSResolver {
    cache: Arc<RwLock<HashMap<String, DomainCacheEntry>>>,
    // ... (Other fields like tracing client, error handler, etc.) ...
}

impl DNSResolver {
    async fn resolve(&self, domain: &str) -> Result<String, Error> {
        let mut cache_entry = self.cache.write().await; 
        if let Some(entry) = cache_entry.get(domain) {
            // Check TTL and update if expired
            if entry.ttl <= Duration::now() - entry.created_at {
                // Remove from cache and re-resolve
                cache_entry.remove(domain); 
                return self.resolve(domain).await; 
            } else {
                log!("Using cached result for {}", domain);
                Ok(entry.status.clone()) // Or return IP address if applicable
            }
        } else {
            // New domain, resolve externally and cache the result
            let status = self.check_domain_availability(domain).await?; 
            cache_entry.insert(domain.to_string(), DomainCacheEntry { ttl: Duration::from_secs(60), status }); // Set TTL here
            Ok(status)
        }
    }

