async function renderFooterScripts(scripts) {
  const cache = {};

  for (const scriptObj of scripts) {
    const key = `${scriptObj.key}-${scriptObj.type}`;

    if (cache[key]) {
      // Use cached script data
      renderScript(cache[key]);
      continue;
    }

    try {
      // Fetch script metadata from API
      const response = await fetch(`https://api.example.com/scripts/${scriptObj.key}`);
      if (!response.ok) {
        throw new Error(`API request failed: ${response.status}`);
      }
      const scriptData = await response.json();

      // Sanitize script code
      const sanitizedCode = sanitizeScript(scriptData.code);

      // Create and render script tag
      renderScript({
        ...scriptObj,
        code: sanitizedCode,
      });

      // Cache script data
      cache[key] = { ...scriptObj, code: sanitizedCode };
    } catch (error) {
      console.error(`Failed to fetch or render script ${scriptObj.key}:`, error);

      // Retry with exponential backoff
      setTimeout(() => {
        renderFooterScripts(scripts); 
      }, Math.pow(2, retryCount));
    }
  }
}

function renderScript(script) {
  const scriptElement = document.createElement('script');
  Object.assign(scriptElement, script);
  document.body.appendChild(scriptElement);
}


```



