#include <mutex>
#include <condition_variable>
#include <queue>

class LogEntry {
public:
    LogEntry(const std::string& message, const std::string& level) : 
        message(message), level(level) {}
    std::string message;
    std::string level;
};

class LogManager {
private:
    std::queue<LogEntry> logBuffer;
    std::mutex bufferMutex;
    std::condition_variable bufferCV;
    bool running = true;

public:
    void insertLogEntry(const std::string& message, const std::string& level) {
        { 
            std::lock_guard<std::mutex> lock(bufferMutex);
            logBuffer.push(LogEntry(message, level));
        }
        bufferCV.notify_one();
    }

    void processLogEntries() {
        while (running) {
            std::unique_lock<std::mutex> lock(bufferMutex);
            bufferCV.wait(lock, [this]{ return !logBuffer.empty(); }); 

            LogEntry entry = logBuffer.front();
            logBuffer.pop();
            lock.unlock();

            // Simulate transmission to cloud service
            std::cout << "Transmitting log entry: " << entry.message << std::endl; 
        }
    }
};

int main() {
    LogManager logger;
    std::thread processingThread(&LogManager::processLogEntries, &logger);

    logger.insertLogEntry("This is a log message", "INFO"); 

    processingThread.join();
    return 0;
}
