async function mergeDataChunks(chunkQueue, metadataApiUrl, payloadSizeThreshold) {
  const chunkBufferPool = new Map(); 

  const processChunk = async (chunkId) => {
    try {
      const chunkData = await fetchChunkData(chunkId); 
      const metadata = await getMetadata(metadataApiUrl + chunkId);
      // ... merge chunk data with metadata
    } catch (error) {
      console.error(`Error processing chunk ${chunkId}:`, error); 
      // ... retry logic with exponential backoff
    }
  };

  const aggregatePayload = async () => {
    let payloadBuffer = Buffer.alloc(0);
    while (chunkBufferPool.size > 0) {
      const chunkData = chunkBufferPool.values().next().value; 
      payloadBuffer = Buffer.concat([payloadBuffer, chunkData]);

      if (payloadBuffer.byteLength >= payloadSizeThreshold) {
        return payloadBuffer;
      }
    }
  };

  // Start processing chunks concurrently 
  const workerPool = []; 
  for (const chunkId of chunkQueue) {
    workerPool.push(processChunk(chunkId)); 
  }

  await Promise.all(workerPool); 
  return aggregatePayload(); 
}

```



**Explanation:**

This code snippet demonstrates the basic structure and logic for a `mergeDataChunks` function that incorporates the requirements you outlined. 

**Key Points:**

- **Asynchronous Data Handling:** The use of `async/await` for `fetchChunkData`, `getMetadata`, and `aggregatePayload` ensures non-blocking execution, allowing the function to handle incoming data chunks concurrently.
