    public STARTUPINFO(int width = 0, int height = 0)
    {
        cb = (uint)Marshal.SizeOf(typeof(STARTUPINFO));
        lpReserved = null;
        lpDesktop = null;
        lpTitle = null;
        dwX = (uint)width;
        dwY = (uint)height;
        dwLength = 0;
        dwFlags = 0;
        wShowWindow = 1; // SW_SHOWNORMAL
        cbReserved2 = 0;
        lpReserved2 = IntPtr.Zero;
    }
}

public class ExternalProcessExecutor
{
    [DllImport("kernel32", SetLastError = true)]
    static extern bool CloseHandle(IntPtr hObject);

    public static int ExecuteAsyncProcess(string command)
    {
        STARTUPINFO startInfo = new STARTUPINFO(100, 50); 
        PROCESS_INFORMATION processInfo;
        CreateProcess("cmd.exe", command, IntPtr.Zero, IntPtr.Zero, true, 0, IntPtr.Zero, null, ref startInfo, out processInfo);

        CloseHandle(processInfo.hProcess);
        CloseHandle(processInfo.hThread);
        return 1; // Success
    }
}


