public async Task<bool> ValidateAccessTokenAsync(string tokenResponse)
{
    try
    {
        var response = JsonConvert.DeserializeObject<dynamic>(tokenResponse);

        if (!response.ContainsKey("access_token") ||
            !response.ContainsKey("expires_in") || 
            !response.ContainsKey("token_type"))
        {
            return false;
        }

        if (response["token_type"].ToString() != "Bearer" || 
