// This is a simplified example and does not cover all the complexities of 
// a production-ready distributed batch processing service.

use tokio::sync::mpsc;
use futures::future::{join_all, FutureExt};

#[derive(Debug)]
struct Job {
    id: String,
    dependencies: Vec<String>,
    resource_requirements: String,
    timeout: u64,
}

// Worker logic simulating processing tasks
async fn process_job(job: Job) -> Result<(), Box<dyn std::error::Error>> {
    println!("Processing job: {}", job.id);
    // Simulate time-consuming task
    tokio::time::sleep(std::time::Duration::from_secs(5)).await;
    Ok(())
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Create a channel for job submission
    let (job_tx, job_rx) = mpsc::channel(10);

    // Spawn worker processes
    let workers = vec![
        process_worker("Worker 1", job_rx.clone()),
        process_worker("Worker 2", job_rx.clone()),
    ];

    // Submit jobs
    job_tx.send(Job {
        id: "job1".to_string(),
        dependencies: vec![],
        resource_requirements: String::from("cpu=2"),
        timeout: 30,
    })
    .await?;

    join_all(workers).await;
    Ok(())
}

// Simulate a worker process
async fn process_worker(name: &str, job_rx: mpsc::Receiver<Job>) {
    loop {
        let job = job_rx.recv().await;
        if let Ok(job) = job {
            println!("{} processing job: {}", name, job.id);
            // Process the job
            process_job(job).await.unwrap(); 
        } else {
            println!("{} exiting", name);
            break;
        }
    }
}


