class ApplicationServer {
public:
    ApplicationServer(size_t numWorkers) : workerThreads(numWorkers) {}

    void AddTask(const Task& task) {
        std::lock_guard<std::mutex> lock(taskMutex);
        tasks.push(task);
        cv.notify_one(); 
    }

    void ScheduleTasks() {
        for (auto& worker : workerThreads) {
            worker.join(); // Ensure workers finish previous tasks
            worker.start();
        }
    }

private:
    struct WorkerThread {
        std::thread thread;
        WorkerThread(const std::function<void()>& func) : thread(&func) {}
        ~WorkerThread() { thread.join(); }
        void start() { thread.detach(); } 
    };

    std::queue<Task> tasks;
    std::condition_variable cv;
    std::mutex taskMutex;
    std::vector<WorkerThread> workerThreads; 
};



