  sqlite3_stmt *stmt;
  rc = sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);
  if (rc != SQLITE_OK) {
    std::cerr << "SQL error: " << sqlite3_errmsg(db) << std::endl;
    sqlite3_finalize(stmt);
    return(1);
  }

  rc = sqlite3_bind_int(stmt, 1, supervisorId);
  if (rc != SQLITE_OK) {
    std::cerr << "Binding parameter error: " << sqlite3_errmsg(db) << std::endl;
    sqlite3_finalize(stmt);
    return(1);
  }

  while ((rc = sqlite3_step(stmt)) == SQLITE_ROW) {
    const char *name = (const char *)sqlite3_column_text(stmt, 0);
    const char *city = (const char *)sqlite3_column_text(stmt, 1);
    const char *address = (const char *)sqlite3_column_text(stmt, 2);

    std::cout << "Name: " << name << ", City: " << city << ", Address: " << address << std::endl;
  }

  sqlite3_finalize(stmt);
  sqlite3_close(db);

  return(0);
}
