// ... (Data structures and external service interaction functions) 

typedef struct SemaphorePool {
    int num_semaphores;
    pthread_mutex_t mutex;
    sem_t *semaphores;
} SemaphorePool;

SemaphorePool* create_semaphore_pool(int num_semaphores, int initial_value) {
    SemaphorePool* pool = malloc(sizeof(SemaphorePool));
    pool->num_semaphores = num_semaphores;
    pthread_mutex_init(&pool->mutex, NULL);
    pool->semaphores = malloc(num_semaphores * sizeof(sem_t));

    for (int i = 0; i < num_semaphores; ++i) {
        sem_init(&pool->semaphores[i], 0, initial_value); // Initialize semaphores with given value
    }

    return pool;
}

void acquire_semaphore(SemaphorePool* pool, int index) {
    pthread_mutex_lock(&pool->mutex);
    sem_wait(&pool->semaphores[index]); 
    pthread_mutex_unlock(&pool->mutex);
}

void release_semaphore(SemaphorePool* pool, int index) {
    pthread_mutex_lock(&pool->mutex);
    sem_post(&pool->semaphores[index]); 
    pthread_mutex_unlock(&pool->mutex);
}

// ... (Functions for error handling, dynamic adjustment, logging, etc.)


int main() {
    SemaphorePool* semaphore_pool = create_semaphore_pool(10, 5); // Initialize pool

    // ... (Thread creation and usage)

    pthread_mutex_destroy(&semaphore_pool->mutex);
    free(semaphore_pool->semaphores);
    free(semaphore_pool);

    return 0;
}
```


Remember: This is a simplified example. A production-ready implementation would require much more detailed error handling, resource management, and concurrency control strategies.']

