from abc import ABC, abstractmethod
import threading

class GeoService(ABC):
    @abstractmethod
    def fetch_tiles(self, region: dict) -> list: pass

    @abstractmethod
    def authenticate(self): pass

class TileCache(object):
    def __init__(self, capacity: int):
        self._capacity = capacity
        self._cache = {}

    def get(self, key):
        if key in self._cache:
            return self._cache[key]
        return None

    def set(self, key, value):
        if len(self._cache) >= self._capacity:
            self._cache.popitem() 
        self._cache[key] = value

class GeoDataAPI(object):
    def __init__(self, api_key: str, cache_size: int = 1024):
        self._api_key = api_key
        self._cache = TileCache(cache_size)
        self._services = {
            "osm": GeoService(),
            # Add other services here
        }

    def fetch_data(self, region: dict, service_name: str) -> list: 
        key = f"{service_name}_{region}"
        if data := self._cache.get(key):
            return data

        service = self._services[service_name]
        data = service.fetch_tiles(region)  
        self._cache.set(key, data)
        return data 
    # Add other methods like authenticate, query etc.

