['```csharp
using System;
using System.Security.Cryptography;

public class Decrypter
{
    public static string DecryptMessage(string encodedMessage, byte[] key, byte[] iv)
    {
        // Convert Base64-encoded message to bytes
        byte[] cipherText = Convert.FromBase64String(encodedMessage);

        // Create TripleDES decryptor with the provided key and IV
        using (var des = new TripleDESCryptoServiceProvider())
        {
            des.Key = key;
            des.IV = iv;

            // Create a decrytor object using the DES algorithm
            using (var decryptor = des.CreateDecryptor())
            {
                // Decrypt the ciphertext
                byte[] plainText = decryptor.TransformFinalBlock(cipherText, 0, cipherText.Length);

                // Return the decrypted message as a string
                return System.Text.Encoding.UTF8.GetString(plainText);
            }
        }
    }
}
