const bookRegex = {
  genesis: /Genesis/,
  exodus: /Exodus/,
  leviticus: /Leviticus/,
  numbers: /Numbers/,
  deuteronomy: /Deuteronomy/,
  joshua: /Joshua/,
  judges: /Judges/,
  rut: /Ruth/,
  firstSamuel: /1 Samuel/,
  secondSamuel: /2 Samuel/,
  kings: /Kings/,
  chronicles: /Chronicles/,
  ezra: /Ezra/,
  nehemiah: /Nehemiah/,
  ester: /Esther/,
  job: /Job/,
  psalms: /Psalms/,
  proverbs: /Proverbs/,
  ecclesiastes: /Ecclesiastes/,
  songOfSolomon: /Song of Solomon/,
  isaiah: /Isaiah/,
  jeremiah: /Jeremiah/,
  lamentations: /Lamentations/,
  ezekiel: /Ezekiel/,
  daniel: /Daniel/,
  hosea: /Hosea/,
  joel: /Joel/,
  amos: /Amos/,
  obadiah: /Obadiah/,
  jonah: /Jonah/,
  Micah: /Micah/,
  nahum: /Nahum/,
  habakkuk: /Habakkuk/,
  zephaniah: /Zephaniah/,
  haggai: /Haggai/,
  zechariah: /Zechariah/,
  malachi: /Malachi/
};

function extractBookNames(text) {
  const bookCounts = {};
  for (const book in bookRegex) {
    bookCounts[book] = 0;
  }

  const words = text.replace(/[^\w\s]/g, '').toLowerCase().split(/\s+/);
  for (const word of words) {
    for (const book in bookRegex) {
      if (bookRegex[book].test(word)) {
        bookCounts[book]++;
      }
    }
  }

  return bookCounts;
}

