public class WebsiteManager
{
    public static string StartWebsite(string directoryPath, string siteName)
    {
        string webConfigPath = Path.Combine(directoryPath, "web.config");

        if (File.Exists(webConfigPath))
        {
            // Start the website using Process class
            ProcessStartInfo startInfo = new ProcessStartInfo();
            startInfo.FileName = "IISExpress.exe"; // Or appropriate command for your web server
            startInfo.WorkingDirectory = directoryPath;
            startInfo.Arguments = $"/site:{siteName}"; 

            Process process = new Process();
            process.StartInfo = startInfo;
            process.Start();

            return "Website started successfully!";
        }
        else
        {
            Console.WriteLine("Web.config file not found.");
            return null;
        }
    }
}
