    if (memory_pool.free_index >= memory_pool.size) {
        fprintf(stderr, "Memory pool exhausted.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    // Assign the new state to the next free slot in the memory pool
    state->id = memory_pool.free_index + 1;
    memory_pool.pool[memory_pool.free_index] = (void *)state;
    memory_pool.free_index++;

    // Insert the state into the database and update the FSA list
    db_insert_state(state);  

    pthread_mutex_unlock(&lock);
}


// Function to get a state from the list by its ID
State *get_state(int state_id) {
    pthread_mutex_lock(&lock);
    // Search for the state in the memory pool
    for (size_t i = 0; i < memory_pool.free_index; i++) {
        State *state = (State *)memory_pool.pool[i];
        if (state->id == state_id) {
            pthread_mutex_unlock(&lock);
            return state;
        }
    }

    // If the state is not found, try to load it from the database
