    // Create a queue to store CA certificates and their private keys.
    const caQueue = [];

    // Process each CA in the specified order.
    for (const caName of caOrder) {
      caQueue.push({
        name: caName,
        certificate: null, 
        privateKey: null,
      });
    }

    // Fetch certificates and private keys asynchronously.
    await Promise.all(
      caQueue.map(async (ca) => {
        try {
          const { certificate, privateKey } = await fetchCaData(ca);
          ca.certificate = certificate;
          ca.privateKey = privateKey;
        } catch (error) {
          console.error(`Error fetching data for CA ${ca.name}:`, error);
        }
      })
    );

    // Construct the PEM file content.
    let pemContent = '';
    for (const ca of caQueue) {
      if (ca.certificate && ca.privateKey) {
        pemContent += `${ca.certificate}\n${ca.privateKey}\n`;
      }
    }

    // Write the PEM file to disk, applying compression if enabled.
    await writePemFile(outputPath, pemContent, compressed);
  } catch (error) {
    console.error('Error generating PEM file:', error);
  }
}


