// Function to insert string 'value2' after the first occurrence of 'value1' in the list, appending if not found.
void insertAfterOrAppend(std::forward_list<std::string>& feed, const std::string& value1, const std::string& value2) {

    // Fetch metadata for both strings (handle errors and retries)
    // ...

    auto before = feed.before_begin(); // iterator pointing to position before the list

    for (auto it = feed.begin(); it != feed.end(); ++it) {
        if (*it == value1) {
            feed.insert(std::next(before), value2);
            return; 
        }
        before = it;
    }

    // Append if value1 not found
    feed.push_back(value2);
}


int main() {
    std::forward_list<std::string> feed = {"apple", "banana", "cherry"};

    insertAfterOrAppend(feed, "banana", "grape"); 

    for (const auto& item : feed) {
        std::cout << item << std::endl;
    }

    return 0;
}
