        public async Task<TState> LoadStateAsync<TState>(string stateKey, CancellationToken cancellationToken) where TState : class
        {
            var ciphertext = await _kmsUrl.GetCiphertextAsync(stateKey); // External call to KMS
            if (ciphertext == null)
            {
                _logger.LogError("Failed to retrieve ciphertext from KMS.");
                return null; 
            }

            try
            {
                var iv = await _kmsUrl.GetIvAsync(stateKey); // External call to KMS
                var decryptedData = _secureStorageApi.DecryptAsync(ciphertext, iv).Result; 

                using (var stream = new MemoryStream(decryptedData))
