// ... Define NetworkEvent, PeerConnection, etc. structures ...

class EventManager {
 public:
  EventManager(size_t max_events) : max_events_(max_events) {}

  void AddEvent(const NetworkEvent& event) {
    std::lock_guard<std::mutex> lock(mutex_);
    while (event_queue_.size() >= max_events_) {
      cv_.wait(lock);
    }
    event_queue_.push(event);
    cv_.notify_one();
  }

  void ProcessEvents() {
    std::thread processing_thread([this]() {
      while (true) {
        NetworkEvent event;
        {
          std::unique_lock<std::mutex> lock(mutex_);
          cv_.wait(lock, [this] { return !event_queue_.empty(); });
          event = event_queue_.front();
          event_queue_.pop();
        }

        // Process the event here
      }
    });

    processing_thread.detach();
  }

 private:
  size_t max_events_;
  std::mutex mutex_;
  std::condition_variable cv_;
  std::queue<NetworkEvent> event_queue_;
};

int main() {
  // ... Initialize logging framework, persistent storage backend ...
  EventManager manager(1000); // Set initial maximum size of the linked list
  manager.ProcessEvents();

  return 0;
}
