    void processEvents() {
        while (true) {
            std::unique_lock<std::mutex> lock(queueMutex_);
            cv_.wait(lock, [this] { return !eventQueue_.empty(); });

            auto event = std::move(eventQueue_.front());
            eventQueue_.pop();
            lock.unlock();

            processEvent(event);
        }
    }

    void addEvent(const Event& event) {
