class Transaction {
public:
    // ... transaction data members ...

    void execute() {
        // ... transaction logic ...
    }
};

class TransactionManager {
private:
    std::mutex mtx; // Global lock for concurrency control
    std::condition_variable cv;
    std::queue<Transaction*> pendingTransactions; 

public:
    void submitTransaction(Transaction* transaction) {
        std::unique_lock<std::mutex> lock(mtx);
        pendingTransactions.push(transaction);
        cv.notify_one(); // Notify waiting threads
    }

    void processTransactions() {
        while (true) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [this] { return !pendingTransactions.empty(); }); 

            Transaction* transaction = pendingTransactions.front();
            pendingTransactions.pop();
            lock.unlock(); // Release the lock for execution

            transaction->execute();
        }
    }
};



