            currentState = State.STARTING;
            // Start the service logic here
            messageBroker.sendMessage(String.format("Service transitioning to RUNNING state"));
            currentState = State.RUNNING;
        } 
    }

    public void stop() {
        if (currentState != State.STOPPING && currentState != State.RUNNING) {
            currentState = State.STOPPING;
            // Stop the service logic here
            messageBroker.sendMessage(String.format("Service transitioning to STOPPED state"));
            currentState = State.STOPPED;
        }
    }

