public class JsonCache<K, V> {
    private final ConcurrentHashMap<K, CachedItem<V>> cache = new ConcurrentHashMap<>();
    private final long ttlInMillis; // TTL in milliseconds

    public JsonCache(long ttlInMillis) {
        this.ttlInMillis = ttlInMillis;
    }

    public CompletableFuture<V> get(K key) {
        CachedItem<V> cachedItem = cache.get(key);
        if (cachedItem != null && !isExpired(cachedItem)) {
            // Return the cached value
        } else {
            // ... logic to fetch data from the API and populate the cache
        }
    }

    private boolean isExpired(CachedItem<V> cachedItem) {
        return clock.now() - cachedItem.getLastAccessedTime() > ttlInMillis;
    }


}



