const app = express();
const port = process.env.PORT || 3000;

// Cache configuration
const redisClient = redis.createClient();

// Placeholder for Old Testament book names
const oldTestamentBooks = ['Genesis', 'Exodus', 'Leviticus', ...];

app.use(express.json());

app.post('/analyze', async (req, res) => {
  try {
    const text = req.body.text;
    const results = {};

    // Process text and count book references
    const matches = text.match(/([^\s]+)(?:\b|\s+)(?:[\w\-]+)?/g); // Basic regex for matching words
    if (matches) {
      matches.forEach(bookName => {
        if (oldTestamentBooks.includes(bookName)) {
          results[bookName] = (results[bookName] || 0) + 1;
        }
      });
    }

    res.json({ results });
  } catch (error) {
    console.error(error);
    res.status(500).send('An error occurred during analysis.');
  }
});

app.listen(port, () => {
  console.log(`Text Analysis Service listening at http://localhost:${port}`);
});
