```csharp
using System;
using System.Security.Cryptography;
using System.Text;

public class EncryptionHelper
{
    public static string DecryptBase64TripleDes(string encodedMessage, byte[] key, byte[] iv) 
    {
        try
        {
            // Decode Base64 string to bytes
            byte[] cipherBytes = Convert.FromBase64String(encodedMessage);

            using (TripleDESCryptoServiceProvider tdes = new TripleDESCryptoServiceProvider())
            {
                tdes.Key = key;
                tdes.IV = iv;
                tdes.Mode = CipherMode.CBC;
                ICryptoTransform decryptor = tdes.CreateDecryptor();

                byte[] decryptedBytes = decryptor.TransformFinalBlock(cipherBytes, 0, cipherBytes.Length);

                return Encoding.UTF8.GetString(decryptedBytes);
            }
        }
        catch (Exception ex)
        {
            // Handle decryption errors gracefully
            Console.WriteLine($"Error decrypting message: {ex.Message}");
            return "Decryption Error"; 
        }
    }
}

```



