import java.util.*; 
import com.google.common.cache.CacheBuilder;
import com.google.common.cache.CacheLoader;
import com.google.common.cache.LoadingCache;

public class DistributedCachingSystem {

    private Map<String, LoadingCache<String, Object>> caches = new ConcurrentHashMap<>();

    public DistributedCachingSystem() {
        // Initialize gossip protocol 
        GossipProtocol gossip = new GossipProtocol();
        gossip.start(); // Start the gossip loop in a separate thread
    }

    public void put(String cacheName, String key, Object value) {
        LoadingCache<String, Object> cache = caches.computeIfAbsent(cacheName, k -> {
            return CacheBuilder.newBuilder()
                    .maximumSize(10000) // Example max size
                    .expireAfterWrite(5, TimeUnit.MINUTES) // TTL 
                    .removalListener((key, value) -> {
                        // Handle removal events (e.g., log, update gossip protocol)
                    })
                    .build(new CacheLoader<String, Object>() {
                        @Override
                        public Object load(String key) throws Exception {
                            return getValueFromDatabase(key); // Fetch from database on miss
                        }
                    });
        });

        cache.put(key, value); 
    }

    public Object get(String cacheName, String key) {
        LoadingCache<String, Object> cache = caches.get(cacheName);
        if (cache != null) {
            return cache.getUnchecked(key);
        } else {
            // Handle cache miss - potentially fetch from database or return a default value
            return null; 
        }
    }

    // ... other methods for eviction, health checks, etc.


}
```



