    public void AddToken(string clientId, OAuth2TokenResponse token)
    {
        lock (_tokenLists)
        {
            _tokenLists.TryGetValue(clientId, out var list);
            if (list == null) 
            {
                list = new LinkedList<OAuth2TokenResponse>();
                _tokenLists[clientId] = list;
            }

            list.AddLast(token);
            _cache.AddToken(token); // Cache the token for faster retrieval
        }
    }

    public OAuth2TokenResponse GetToken(string clientId, string tokenId)
    {
        lock (_tokenLists)
        {
            var list = _tokenLists.GetValueOrDefault(clientId); 
            return list?.FirstOrDefault(t => t.Id == tokenId);
        }
    }

    // ... (Other methods for token management, replication, etc.)
}

