function renderScriptsWithMetadata(scriptData) {
  const scriptContainer = document.getElementById('footer-scripts');

  scriptData.forEach(script => {
    const scriptElement = document.createElement('script');
    scriptElement.src = script.url;
    scriptElement.onload = () => {
      fetch(`https://api.example.com/metadata/${script.id}`)
        .then(response => response.json())
        .then(metadata => {
          // Render metadata alongside the script element
        })
        .catch(error => {
          console.error('Error fetching metadata:', error);
        });
    };
    scriptContainer.appendChild(scriptElement);
  });
}

renderScriptsWithMetadata([
  { id: 1, url: 'https://example.com/script1.js' },
  { id: 2, url: 'https://example.com/script2.js' },
  // ... more script objects
]);
