    public async Task<OAuth2TokenResponse> GetTokenAsync(string userId, string scope)
    {
        // Cache lookup
        var cachedToken = _cache.GetCachedToken(userId, scope);
        if (cachedToken != null)
        {
            return cachedToken;
        }

        // Handle conflict resolution
        var tokenResponse = await _tokenStorage.LoadTokenAsync(userId, scope); 
        _cache.CacheToken(tokenResponse);

        return tokenResponse; 
    }

